class Agenthub < Formula
  desc "Local gateway between AI clients and MCP servers"
  homepage "https://github.com/dinstein/agent-hub"
  version "0.20.1"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.20.1/agenthub-0.20.1-b43bf1d-darwin-arm64.tar.gz"
      sha256 "5f4cedd6bf4afdaa8149a34ae98e6cc2f45453b58db844a6cdbdc1c1ee83a85f"
    end
    on_intel do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.20.1/agenthub-0.20.1-b43bf1d-darwin-amd64.tar.gz"
      sha256 "49e14a1de48066ea4724c12d10cd1adcaa4d91689055ef7f2dd7c44038176ceb"
